// ancient motive chips and links to modern solutions
const CH=['SAVE ENERGY','FIND FOOD','FIND LOVE','WIN ACCEPTANCE','REDUCE UNCERTAINTY','GAIN STATUS'], POS=[0,1,3,4,5,2], chips=CH.map((s,i)=>{const q=POS[i],x=120+(q%3)*460,y=250+Math.floor(q/3)*84,g=mk('g',{},$('chips'));
  const r=mk('rect',{x:x,y:y,width:440,height:64,rx:32,fill:'var(--stage)',stroke:'var(--ink)','stroke-width':4},g);
  const tx=mk('text',{x:x+220,y:y+41,'font-size':22,'text-anchor':'middle',style:'font-family:var(--mono);letter-spacing:.04em;fill:var(--ink)'},g);tx.textContent=s;return [g,r]});
const LK=[[2,0],[3,1],[4,2]].map(([c,m])=>{const q=POS[c],x1=120+(q%3)*460+220,y1=250+Math.floor(q/3)*84+64,x2=120+m*460+220;
  return mk('path',{d:'M'+x1+' '+y1+'C'+x1+' '+(y1+80)+' '+x2+' '+(560-80)+' '+x2+' 560',fill:'none',stroke:'var(--gain)','stroke-width':5,'stroke-dasharray':'8 8'},$('links'))});
// prediction chain
const CN=['CUE','PREDICTION','FEELING','CRAVING'], chain=CN.map((s,i)=>{const x=120+i*360,g=mk('g',{},$('chain'));
  const r=mk('rect',{x:x,y:340,width:280,height:120,rx:16,fill:'var(--stage)',stroke:'var(--ink)','stroke-width':5},g);
  const tx=mk('text',{x:x+140,y:410,'font-size':26,'text-anchor':'middle',style:'font-family:var(--mono);letter-spacing:.04em;fill:var(--ink)'},g);tx.textContent=s;
  if(i<3)mk('path',{d:'M'+(x+290)+' 400h50m-16-16 16 16-16 16',fill:'none',stroke:'var(--muted)','stroke-width':5,'stroke-linecap':'round','stroke-linejoin':'round'},g);
  return [g,r,tx]});
// ritual reps
const reps=[];for(let i=0;i<8;i++){const x=140+i*120;reps.push(mk('circle',{cx:x,cy:630,r:22},$('reps')));if(i<7)mk('path',{d:'M'+(x+26)+' 630h68',stroke:'var(--line)','stroke-width':4},$('reps'))}
const W={ot0:560,ot1:470,rt0:560,rt1:500};
function measure(){for(const k in W){try{const v=$(k).getComputedTextLength();if(v>0)W[k]=v}catch(e){}}}
measure(); if(document.fonts&&document.fonts.ready)document.fonts.ready.then(()=>{measure();render(t)});

render:
// title: the lens searches for the root
$('lens').setAttribute('transform','translate('+(40*Math.sin(t*.8)).toFixed(1)+' '+(60*p(t,.3,1.8)+14*Math.sin(t*1.3)).toFixed(1)+')');

// Carr
[TM.giveup,TM.stress].forEach((a,i)=>{rise($('o'+i),p(u,a,a+.4)); strike('os'+i,W['ot'+i],p(u,a+.8,a+1.4)); rise($('n'+i),p(u,a+1.2,a+1.8))});
rise($('quit'),p(u,TM.quit,TM.quit+.6));

// iceberg
let wv='M0 420'; for(let x=0;x<=1600;x+=40)wv+='L'+x+' '+(420+6*Math.sin(x/60+t*2)).toFixed(1); $('wave').setAttribute('d',wv);
rise($('u0'),p(u,TM.cig,TM.cig+.4)); rise($('u1'),p(u,TM.scroll,TM.scroll+.4));
[TM.relief,TM.conn,TM.conn+.8,TM.conn+1.6].forEach((a,i)=>rise($('d'+i),p(u,a,a+.4)));

// ancient motives
chips.forEach((c,i)=>{const a=TM.motives+i*1.4; rise(c[0],p(u,a,a+.4))});
[TM.dating,TM.social,TM.search].forEach((a,i)=>{rise($('m'+i),p(u,a,a+.4)); LK[i].setAttribute('opacity',p(u,a,a+.4)); chips[[2,3,4][i]][1].setAttribute('stroke',u>=a?'var(--gain)':'var(--ink)')});
rise($('same'),p(u,TM.dating-1.2,TM.dating-.6));

// prediction chain
chain.forEach((c,i)=>{const a=TM.signal+i*.4; rise(c[0],p(u,a,a+.4))});
rise($('miss'),p(u,TM.signal,TM.signal+.5));
const ch=u>=TM.change; chain[1][1].style.fill=ch?'var(--gain)':'var(--stage)'; chain[1][1].style.stroke=ch?'var(--gain)':'var(--ink)';
chain[1][2].textContent=ch?'NEW PREDICTION':'PREDICTION'; chain[3][2].textContent=ch?'CRAVING CHANGES':'CRAVING';
chain[3][1].setAttribute('stroke-dasharray',ch?'10 10':'none');
rise($('chg'),p(u,TM.change,TM.change+.6));

// reframe
[TM.run,TM.save].forEach((a,i)=>{rise($('r'+i+'o'),p(u,a,a+.4)); strike('rs'+i,W['rt'+i],p(u,a+1.2,a+1.8)); rise($('r'+i+'n'),p(u,a+1.6,a+2.2))});

// nervous or excited
const ex=u>=TM.excite, beat=1+.08*Math.pow(Math.abs(Math.sin(t*4.2)),6);
$('heart').setAttribute('transform','translate(400 470) scale('+beat.toFixed(3)+')'); $('heartP').style.fill=ex?'var(--gain)':'var(--loss)';
let pe=''; for(let x=160;x<=640;x+=4){const k=((x+t*240)%120+120)%120; pe+=x+','+(700-(k<50?0:k<58?-(k-50)*5:k<66?-40+(k-58)*12:k<74?56-(k-66)*8:0)).toFixed(1)+' '} $('ecg').setAttribute('points',pe);
rise($('lblN'),p(u,TM.nervous,TM.nervous+.4)); strike('lnS',380,p(u,TM.excite-.3,TM.excite+.3)); rise($('lblE'),p(u,TM.excite,TM.excite+.5)); rise($('works'),p(u,TM.excite+.6,TM.excite+1.2));

// motivation ritual
reps.forEach((c,i)=>{const on=u>=TM.pair+i*.5; c.setAttribute('fill',on?'var(--gain)':'var(--line)')});
rise($('zone'),p(u,TM.pair+3.6,TM.pair+4.2)); rise($('ed'),p(u,TM.ed,TM.ed+.6));

// unattractive: the magnet pushes the habit away
const c=(t%3)/3, push=c<.7?ease(c/.7):1; $('pushed').setAttribute('cy',(540+200*push).toFixed(1)); $('pushed').setAttribute('opacity',(c<.85?1:1-(c-.85)/.15).toFixed(2));
[TM.gain,TM.gain+.5,TM.gain+1,TM.gain+1.5].forEach((a,i)=>rise($('g'+i),p(u,a,a+.4)));

// close
rise($('qa'),p(u,TM.q,TM.q+.5)); rise($('qb'),p(u,TM.q+.4,TM.q+.9)); rise($('qc'),p(u,TM.q+.8,TM.q+1.3));
